@import 'c/rlySharedStyles';

.rr-wt { background: #fff; border: 1px solid #e5e5e5; border-radius: 4px; box-shadow: 0 2px 2px rgba(0, 0, 0, 0.05); padding: 12px 14px; display: flex; flex-direction: column; gap: 10px; margin-bottom: 12px; }
.rr-wt-head { display: flex; align-items: center; gap: 10px; }
.rr-grow { flex: 1 1 auto; min-width: 0; }
.rr-weak { color: #5c5c5c; }
.rr-mono { font-family: Menlo, Consolas, monospace; font-size: 12px; }
.rr-break { overflow-wrap: anywhere; }
.rr-wt-form { display: flex; flex-direction: column; gap: 10px; border: 1px solid #e5e5e5; border-radius: 4px; padding: 10px 12px; background: #fafaf9; }
.rr-grid2 { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 10px; }
.rr-wt-actions { display: flex; gap: 8px; justify-content: flex-end; }
.rr-table { border: 1px solid #e5e5e5; border-radius: 4px; overflow-x: auto; }
.rr-tr { display: grid; grid-template-columns: 26px minmax(130px, 1.2fr) minmax(120px, 1.3fr) minmax(120px, 1.1fr) 100px minmax(330px, auto); gap: 8px; align-items: center; padding: 7px 10px; border-bottom: 1px solid #f1f1f1; font-size: 12.5px; }
.rr-tr:last-child { border-bottom: 0; }
.rr-tr > .rr-msg { grid-column: 2 / -1; }
.rr-th { background: #fafaf9; font-size: 11px; text-transform: uppercase; letter-spacing: 0.03em; color: #5c5c5c; }
.rr-tr-off { color: #5c5c5c; }
.rr-acts { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.rr-pill { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 9px; border-radius: 10px; white-space: nowrap; }
.rr-pill-run { background: #eef4ff; color: #0176d3; }
.rr-pill-vio { background: #f2ecfc; color: #5a1ba9; }
.rr-pill-none { background: #f3f3f3; color: #5c5c5c; }
.rr-try { display: flex; gap: 12px; align-items: flex-end; flex-wrap: wrap; }
.rr-try lightning-input { width: 220px; }
.rr-ok { color: #2e844a; margin: 0 0 8px; }
.rr-bad { color: #8e030f; margin: 0 0 8px; }
.rr-switches { display: flex; flex-direction: column; gap: 8px; border-top: 1px solid #e5e5e5; padding-top: 10px; }
.rr-narrow { max-width: 260px; }
